		public void SetPause(bool isPause) {
            float speed = isPause ? 0.0f : 1.0f;
            this.isPause = isPause;

            for (int i = 0; i < BattleViewDefine.POKEMON_NUM; i++)
            {
                if (trainers[i] != null)
                    trainers[i].SetAnimSpeed(speed);

                var pokemon = pokemons[i];
                if (pokemon != null)
                {
                    pokemon.SetAnimSpeed(speed);
                    pokemon.Entity.SetBlinkEnabled(!isPause);

                    var animationPlayer = pokemon.Entity.GetAnimationPlayer();
                    if (animationPlayer != null && animationPlayer.IsValidCurrentPlayable)
                    {
                        if (isPause)
                            animationPlayer.Stop();
                        else
                            animationPlayer.Resume();
                    }
                }
            }

            foreach (var pair in m_iPtrSequenceSystem.GetModelHashTable().RawElements)
            {
                foreach (var entity in pair.Value)
                    entity.SetAnimSpeed(speed);
            }

            foreach (var pair in m_iPtrSequenceSystem.GetParticleHashTable().RawElements)
            {
                foreach (var effect in pair.Value)
                {
                    if (isPause)
                        effect?.Effect?.particleSystem.Pause();
                    else
                        effect?.Effect?.particleSystem.Play();
                }
            }
        }
