		public void SeqComFunc_MoveRelativePoke(global::Dpr.Battle.View.ITranslationObject iPtrObj, int frame, global::Dpr.Battle.View.RELARIVE_POKE_OPTION opt, bool isTrainer = false) {
			BOPokemon pokeModel = GetPokeModel(opt.m_vpos);
			if (pokeModel != null && pokeModel.IsEnable)
			{
				Vector3 pos = Vector3.zero;
				Vector3 rot = Vector3.zero;
				Vector3 scale = Vector3.one;
				SeqComFunc_GetPokeRelativePos(ref opt, ref pos, ref rot, ref scale, isTrainer);

				if (opt.m_rate != 100)
				{
					pos = (pos - iPtrObj.GetTranslationVec()) * (opt.m_rate * 0.01f);
					pos = iPtrObj.GetTranslationVec() + pos;
				}

				if (opt.m_autoRotateModel)
					iPtrObj.SetRotationVec(rot);

				if (opt.m_adjustScale && !isTrainer)
					iPtrObj.SetScaleOffset(scale);

				Vector3 nowPos = iPtrObj.GetTranslationVec();
				BattleSequenceSystem.SetVectorSelectElem(ref nowPos, ref pos, opt.m_targetElem);

				if (frame == 0)
				{
					iPtrObj.SetTranslationVec(nowPos);
				}
				else
				{
					var task = new TaskVectorControl(iPtrObj.GetTranslationVec(), nowPos, ((EaseFunc)opt.m_moveType).GetEase(), frame, x => iPtrObj.SetTranslationVec(x));
					float startTime = m_iPtrSequenceSystem.CurrentTime;
#if PC_UNLOCKED_FPS
					task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / PcPlatform.PcFrameClock.LogicRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#else
					task.SetStartTime(startTime).SetEndTime(startTime + 1.0f / Application.targetFrameRate * frame).SetAdvanceMode(Task.AdvanceMode.Time);
#endif
					m_iPtrTaskManager.RegisterTask(task, true);
				}
			}
		}
