		public bool CheckCanPlayCommand(global::Dpr.SequenceEditor.CommandParam param) {
			int value = -1;

			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_POKE_SIZE, out value))
			{
				switch ((GRP_OPT_POKE_SIZE)value)
				{
					case GRP_OPT_POKE_SIZE.GRP_OPT_ATK_L:
					{
						var pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!(pokeModel != null && pokeModel.IsEnable && pokeModel.GetSize() == Size.L))
							return false;
						break;
					}

					case GRP_OPT_POKE_SIZE.GRP_OPT_ATK_UNDER_M:
					{
						var pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!(pokeModel != null && pokeModel.IsEnable && pokeModel.GetSize() < Size.L))
							return false;
						break;
					}

					case GRP_OPT_POKE_SIZE.GRP_OPT_DEF_L:
					case GRP_OPT_POKE_SIZE.GRP_OPT_DEF_UNDER_M:
					case GRP_OPT_POKE_SIZE.GRP_OPT_DEF_SIZE_OTHER:
						// Shipped: SeqComFunc_GetTargetPokeNum always throws (SHIPPED-THROW @01bdb060), so clang treats the call as
						// noreturn and drops every instruction after it (@01bdc528 / 01bdc52c is the end of the function): the
						// per-target size checks that followed in source are unreachable and unrecoverable; behaviour = the throw.
						SeqComFunc_GetTargetPokeNum(false);
						break;

					case GRP_OPT_POKE_SIZE.GRP_OPT_ATK_SIZE_OTHER:
					{
						var pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (pokeModel && pokeModel.IsEnable && pokeModel.GetSize() <= Size.L)
							return false;
						break;
					}
				}
			}

			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_POKE_LAND, out value))
			{
				BOPokemon pokeModel;
				switch ((GRP_OPT_POKE_LAND)value)
				{
					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_NORMAL:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!((pokeModel != null && pokeModel.GetPokeLandingType() == LandingType.NORMAL) || (pokeModel != null && pokeModel.GetPokeLandingType() == LandingType.NONE)))
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_FLY:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!(pokeModel != null && pokeModel.GetPokeLandingType() == LandingType.FLY))
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_GROUND:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!pokeModel || pokeModel.GetPokeLandingType() != LandingType.GROUND)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_EX_NORMAL:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!((pokeModel && pokeModel.GetPokeLandingEXType() == LandingType.NORMAL) || (pokeModel && pokeModel.GetPokeLandingEXType() == LandingType.NONE)))
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_EX_FLY:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!pokeModel || pokeModel.GetPokeLandingEXType() != LandingType.FLY)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_EX_GROUND:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!pokeModel || pokeModel.GetPokeLandingEXType() != LandingType.GROUND)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_EX_FL_GRO:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!pokeModel || pokeModel.GetPokeLandingEXType() != LandingType.EX_FLY_GROUND)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE_LAND_EX_GRO_FL:
						pokeModel = GetPokeModel(m_comTargetPoke[0]);
						if (!pokeModel || pokeModel.GetPokeLandingEXType() != LandingType.EX_GROUND_FLY)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE2_LAND_NORMAL:
						pokeModel = GetPokeModel(m_comTargetPoke[1]);
						if (!((pokeModel && pokeModel.GetPokeLandingType() == LandingType.NORMAL) || (pokeModel && pokeModel.GetPokeLandingType() == LandingType.NONE)))
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE2_LAND_FLY:
						pokeModel = GetPokeModel(m_comTargetPoke[1]);
						if (!pokeModel || pokeModel.GetPokeLandingType() != LandingType.FLY)
							return false;
						break;

					case GRP_OPT_POKE_LAND.GRP_OPT_POKE2_LAND_GROUND:
						pokeModel = GetPokeModel(m_comTargetPoke[1]);
						if (!pokeModel || pokeModel.GetPokeLandingType() != LandingType.GROUND)
							return false;
						break;
				}
			}

			if (param.TryGetOptionValue(GRP_OPT.GRP_OPT_SCENE_TYPE, out value))
			{
				// `(value - 1) > 1u` @01bdc4d8: battle and contest scene-type groups are skipped in the seal preview.
				switch ((GRP_OPT_SCENE_TYPE)value)
				{
					case GRP_OPT_SCENE_TYPE.GRP_OPT_SCENE_TYPE_BATTLE:
					case GRP_OPT_SCENE_TYPE.GRP_OPT_SCENE_TYPE_CONTEST:
						return false;
				}
			}

			return true;
		}
		public void OnLateUpdate(float deltaTime) {
			if (m_isFinalize || isPause)
				return;

			float currentSequenceTime = m_iPtrSequenceSystem != null ? m_iPtrSequenceSystem.CurrentTime : 0.0f;

			if (!__IsSuspendSequenceSystem__)
			{
				if (m_iPtrSequenceSystem != null)
					m_iPtrSequenceSystem.LateUpdate(deltaTime);

				if (m_iPtrTaskManagerLate != null)
					m_iPtrTaskManagerLate.OnUpdate(deltaTime, currentSequenceTime, 1);

				if (m_iPtrCameraSystem != null)
					m_iPtrCameraSystem.OnLateUpdate(deltaTime);
			}

			BattleJobSystem.OnUpdatePostJob(deltaTime);
		}
		private void __UpdateSequence__() {
			var sequenceSystem = m_iPtrSequenceSystem;
			if (sequenceSystem == null)
				return;

			switch (m_sequenceSeq)
			{
				case BattleViewSystem.SequenceSeq.START_LOAD:
					if (sequenceSystem.IsLoadedSequenceFile)
					{
						sequenceSystem.SetupSequence();
						sequenceSystem.StartPreLoad();
						m_sequenceSeq = BattleViewSystem.SequenceSeq.WAIT_PRELOAD;
					}
					break;

				case BattleViewSystem.SequenceSeq.WAIT_PRELOAD:
					if (sequenceSystem.IsPreLoaded)
					{
						// Shipped: every DprPokemonMoveResetAll command spanning frame 116 only is marked as already called.
						foreach (var param in sequenceSystem.FindCommands(CommandNo.DprPokemonMoveResetAll))
						{
							if (param.StartFrame == 116 && param.EndFrame == 116)
								param.IsAlreadyCalled = true;
						}

						sequenceSystem.SetupPreLoad();
						sequenceSystem.SetPause(true);
						m_isSoundPlayingFinishCheckInvalid = false;
						m_soundPlayingFinishWaitCount = 0;
						m_sequenceSeq = BattleViewSystem.SequenceSeq.WAIT_LOAD;
					}
					break;

				case BattleViewSystem.SequenceSeq.WAIT_LOAD:
					if (__IsWazaMsgCommandSeq__())
					{
						__StartWazaMsgCommand__();
						m_sequenceSeq = BattleViewSystem.SequenceSeq.WAIT_WAZA_MSG;
					}
					else
					{
						sequenceSystem.SetPause(false);
						m_sequenceSeq = BattleViewSystem.SequenceSeq.UPDATE_SEQUENCE;
					}
					break;

				case BattleViewSystem.SequenceSeq.WAIT_WAZA_MSG:
					if (__WaitWazaMsgCommand__())
					{
						sequenceSystem.SetPause(false);
						m_sequenceSeq = BattleViewSystem.SequenceSeq.UPDATE_SEQUENCE;
					}
					break;

				case BattleViewSystem.SequenceSeq.UPDATE_SEQUENCE:
					if (!__IsSuspendSequenceSystem__ && sequenceSystem.IsFinishSequence && IsAllTaskFinished)
					{
						sequenceSystem.SetPause(true);
						m_sequenceSeq = BattleViewSystem.SequenceSeq.FINISH;
					}
					break;

				case BattleViewSystem.SequenceSeq.FINISH:
					if (m_seqKeepResource)
					{
						m_sequenceSeq = BattleViewSystem.SequenceSeq.NONE;
						m_seqKeepResource = false;
						break;
					}

					sequenceSystem.DeleteAllVector();
					m_sequenceSeq = BattleViewSystem.SequenceSeq.SOUND_WAIT;
					break;

				case BattleViewSystem.SequenceSeq.SOUND_WAIT:
					m_sequenceSeq = BattleViewSystem.SequenceSeq.NONE;
					break;
			}
		}
		private void __UpdateSuspendSequenceSystem__() {
			if (m_iPtrSequenceSystem == null)
				return;

			if (m_pComWaitFunc != null && m_pComWaitFunc.Invoke())
				m_pComWaitFunc = null;

			m_wazaParam.m_frame = m_iPtrSequenceSystem.CurrentFrame;
			m_wazaParam.m_elaspedTime = m_iPtrSequenceSystem.CurrentTime;

			if (m_iPtrSequenceSystem.IsPause)
				return;

#if PC_UNLOCKED_FPS
			if (m_wazaParam.m_elaspedTime >= 1.0f / PcPlatform.PcFrameClock.LogicRate * m_wazaParam.m_keyDiffFrame && !m_wazaParam.m_isPlayMotion)
#else
			if (m_wazaParam.m_elaspedTime >= 1.0f / Application.targetFrameRate * m_wazaParam.m_keyDiffFrame && !m_wazaParam.m_isPlayMotion)
#endif
			{
				m_wazaParam.m_isPlayMotion = true;

				var vpos = m_comTargetPoke[0];
				if (vpos == BtlvPos.BTL_VPOS_ERROR)
					return;

				var pokeModel = pokemons[(int)vpos];
				if (pokeModel != null)
					pokeModel.ChangeAnimStatePoke(m_wazaParam.m_attackMotion, 0.15f, 0.0f);

				return;
			}

			if (!m_wazaParam.m_enableKeyAdjust)
				return;

			if (m_wazaParam.m_keyDiffFrame >= 0)
			{
				m_wazaParam.m_enableKeyAdjust = false;
				return;
			}

#if PC_UNLOCKED_FPS
			m_wazaParam.m_keyDiffFrame += 2 * __PcTicks__;
#else
			m_wazaParam.m_keyDiffFrame += 2;
#endif
		}
		private void __GetDefaultTrainerPos__(global::Dpr.Battle.Logic.BtlvPos vPos, ref global::UnityEngine.Vector3 pPos, ref int pDeg, bool isOrigin, global::Dpr.SequenceEditor.SEQ_DEF_DEFAULT_PLACEMENT placement) {
			pPos = Vector3.zero;
			pDeg = 180;

			var rule = GetBattleRule();
			var pokeModel = pokemons[(int)vPos];
			Size pokeSize = pokeModel != null ? pokeModel.GetSize() : Size.M;
			m_defaultPlacementData.GetTrainerPlacementData(rule, vPos, pokeSize, placement, out pPos, out pDeg);
		}
