		private void __SetComTargetReset__() {
			for (int i = 0; i < (int)BtlvPos.BTL_VPOS_NUM; i++)
				m_comTargetDamage[i] = BtlvPos.BTL_VPOS_ERROR;

			for (int i = 0; i < (int)BattleViewSystem.CommandTarget.MAX; i++)
				m_comTargetPoke[i] = BtlvPos.BTL_VPOS_ERROR;

			for (int i = 0; i < (int)BattleViewSystem.CommandTarget.MAX; i++)
				m_comTargetTrainer[i] = BtlvPos.BTL_VPOS_ERROR;

			for (int i = 0; i < m_effectBallId.Length; i++)
				m_effectBallId[i] = BallId.MONSUTAABOORU;

			for (int i = 0; i < m_effectBallInfo.Length; i++)
				m_effectBallInfo[i] = BtlvBallInfo.Default;
		}
