		private global::Pml.BallId __GetCaptureBall__(global::Dpr.Battle.Logic.BtlvPos vPos) {
			if (pokemons[(int)vPos] == null)
				return BallId.NULL;

			BallId ballId = (BallId)pokemons[(int)vPos].Param.GetGetBall();
			return Pml.Item.ItemManager.IsStrangeBall(ballId) ? BallId.NULL : ballId;
		}
		private global::Dpr.Battle.View.BtlvBallInfo __GetBallInfo__(global::Dpr.Battle.Logic.BtlvPos vPos) {
			m_effectBallInfo[(int)vPos].Clear();
			var affixSealDatas = GetSetupParam().affixSealDatas[(int)vPos];
			m_effectBallInfo[(int)vPos].ballId = __GetCaptureBall__(vPos);
			m_effectBallInfo[(int)vPos].isStrangeBall = Pml.Item.ItemManager.IsStrangeBall(m_effectBallInfo[(int)vPos].ballId);
			m_effectBallInfo[(int)vPos].sealCnt = (byte)affixSealDatas.Length;
			m_effectBallInfo[(int)vPos].affixSealDatas = affixSealDatas;
			return m_effectBallInfo[(int)vPos];
		}
