		public void UnInitialize() {
			if (global::Dpr.Battle.View.Systems.BattleViewUISystem.Instance != null)
				global::Dpr.Battle.View.Systems.BattleViewUISystem.Instance.SetActive(true);
			global::SmartPoint.AssetAssistant.Sequencer.update -= OnUpdate;
			global::SmartPoint.AssetAssistant.Sequencer.lateUpdate -= OnLateUpdate;
			_sealPreviewController = null;
			_initializeSequenceState = global::Dpr.Battle.View.Systems.BattleViewSystem.InitializeSequenceStateType.Unregistered;
			_loadObjectCnt = 0;
		}
		public bool Initialize() {
			switch (_initializeSequenceState)
			{
				case BattleViewSystem.InitializeSequenceStateType.Unregistered:
				case BattleViewSystem.InitializeSequenceStateType.InitSystem:
				{
					m_iPtrSequenceSystem = new BattleSequenceSystem(this);
					m_iPtrCameraSystem = new SealPreviewCameraSystem(this, _sealPreviewController.GetSequenceCameraObject().GetComponent<BOCamera>());
					m_battleDataTable = BattleDataTableManager.Instance.BattleDataTable;
					m_defaultPlacementData = BattleDataTableManager.Instance.BattleDefaultPlacementData;
					m_uPtrModelHash = new Dictionary<int, HashSet<ObjectEntity>>(BattleViewDefine.DEFAULT_HASH_MODEL_MAX);
					m_uPtrSoundPlayingIDHash = new Stack<Tuple<int, uint, uint>>(BattleViewDefine.DEFAULT_HASH_SOUND_PLAYING_ID_MAX);
					m_uPtrParticleVectorHash = new Dictionary<int, HashSet<BtlvEffectInstance>>(BattleViewDefine.DEFAULT_HASH_MODEL_MAX);
					m_iPtrTaskManager = new TaskManager(104);
					m_iPtrTaskManagerLate = new TaskManager();
					m_iPtrTaskManagerAlways = new TaskManager();
					_initializeSequenceState = BattleViewSystem.InitializeSequenceStateType.WaitLoadData;
					return false;
				}

				case BattleViewSystem.InitializeSequenceStateType.WaitLoadData:
				{
					var setupParam = GetSetupParam();
					var trainerParams = setupParam.trainerParams;
					var pokemonParams = setupParam.pokemonParams;

					if (BattleViewUISystem.Instance != null)
						BattleViewUISystem.Instance.SetActive(false);

					for (int i = 0; i < trainerParams.Length; i++)
					{
						if (trainerParams[i].HasValue)
							LoadTrainerModel(trainerParams[i].Value, (BtlvPos)i);
					}

					for (int i = 0; i < pokemonParams.Length; i++)
					{
						if (pokemonParams[i] != null)
							LoadPokemonModel(pokemonParams[i], (BtlvPos)i);
					}

					_initializeSequenceState = BattleViewSystem.InitializeSequenceStateType.WaitLoadGraphic;
					return false;
				}

				case BattleViewSystem.InitializeSequenceStateType.WaitLoadGraphic:
					if (_loadObjectCnt <= 0)
					{
						_initializeSequenceState = BattleViewSystem.InitializeSequenceStateType.SetupData;
						var camera = m_iPtrCameraSystem?.GetBattleCamera(SequenceCameraSystem.CameraStateType.Main);
						if (camera != null)
							camera.IsEnabled = true;
					}
					return false;

				case BattleViewSystem.InitializeSequenceStateType.SetupData:
					_initializeSequenceState = BattleViewSystem.InitializeSequenceStateType.Finish;
					StartGround();
					ResetAll();
					return true;

				case BattleViewSystem.InitializeSequenceStateType.Finish:
					return true;

				default:
					return false;
			}
		}
		private global::System.Collections.IEnumerator SetupBackground() {
			var arenaData = GetSetupParam().arenaData;
			var connector = GameManager.connector;
			AssetRequestOperation bgRequestOperatioin = null;
			AssetRequestOperation skyRequestOperatioin = null;

			bgRequestOperatioin = AssetManager.AppendAssetBundleRequest(arenaData.GroundAssetBundleName, true, null, null);
			_loadObjectCnt++;

			if (!string.IsNullOrEmpty(arenaData.SkyAssetBundleName))
			{
				_loadObjectCnt++;
				skyRequestOperatioin = AssetManager.AppendAssetBundleRequest(arenaData.SkyAssetBundleName, true, null, null);
			}

			AssetManager.DispatchRequests();

			// do-while: the first pass runs (and yields once) even when both requests are null (@019c5534..553c).
			do
			{
				if (bgRequestOperatioin != null && !bgRequestOperatioin.keepWaiting)
				{
					var bg = UnityEngine.Object.Instantiate(bgRequestOperatioin.assetBundleRequest.cache.loadedFirstAsset, connector.bgCacheObjects) as GameObject;
					foreach (var activator in bg.GetComponentsInChildren<EffectActivator>(true))
						yield return activator.ActivateOperation(connector.bgCacheObjects);

					AssetManager.UnloadAssetBundle(bgRequestOperatioin.assetBundleRequest.uri);
					bgRequestOperatioin = null;
					_loadObjectCnt--;
				}

				if (skyRequestOperatioin != null && !skyRequestOperatioin.keepWaiting)
				{
					UnityEngine.Object.Instantiate(skyRequestOperatioin.assetBundleRequest.cache.loadedFirstAsset, connector.bgCacheObjects);
					AssetManager.UnloadAssetBundle(skyRequestOperatioin.assetBundleRequest.uri);
					skyRequestOperatioin = null;
					_loadObjectCnt--;
				}

				yield return null;
			}
			while (bgRequestOperatioin != null || skyRequestOperatioin != null);

			connector.renderSettings = arenaData.RenderSettings;
			EnvironmentController.global.SetLight(arenaData.RenderSettings, PeriodOfDay.Daytime, 0.0f, 0.0f);
		}
		private void LoadTrainerModel(global::DPData.MYSTATUS status, global::Dpr.Battle.Logic.BtlvPos vPos) {
			_loadObjectCnt++;
			var connector = GameManager.connector;

			var myStatus = new MyStatus();
			myStatus.Deserialize(status);
			Dpr.Trainer.TrainerType trainerType = myStatus.GetSex() == Sex.MALE ? Dpr.Trainer.TrainerType.BOY : Dpr.Trainer.TrainerType.GIRL;
			// Shipped: the sheet row is looked up and never used (@01bdcaa4, result discarded).
			var trainerTypeData = TrainerSystem.GetTrainerType(trainerType);

			AssetManager.AppendAssetBundleRequest(string.Format("persons/battle/{0}", myStatus.GetModelID()), true, (eventType, assetName, asset) =>
			{
				if (eventType == RequestEventType.Activated && asset is GameObject)
				{
					_loadObjectCnt--;
					GameObject go = UnityEngine.Object.Instantiate(asset as GameObject);
					var entity = go.GetComponent<BattleCharacterEntity>();
					if (entity != null)
					{
						var simpleParam = TrainerSimpleParam.Factory(trainerType);
						simpleParam.colorID = PlayerWork.colorID;
						entity.Initialize(simpleParam, true);
					}

					var boTrainer = go.AddComponentIfNecessary<BOTrainer>();
					if (boTrainer != null)
					{
						boTrainer.Initialize(vPos, null);
						boTrainer.transform.SetParent(connector.characterCacheObjects);
					}

					trainers[(int)vPos] = boTrainer;
				}
			}, null);
			AssetManager.DispatchRequests();
		}
		private void LoadPokemonModel(global::Pml.PokePara.PokemonParam param, global::Dpr.Battle.Logic.BtlvPos vPos) {
			_loadObjectCnt++;
			var connector = GameManager.connector;

			var catalog = GameData.DataManager.GetPokemonCatalog(param.GetMonsNo(), param.GetFormNo(), param.GetSex(), param.IsRare(), false);
			if (catalog == null)
				catalog = GameData.DataManager.GetPokemonCatalog(MonsNo.PIKATYUU, 0, Sex.FEMALE, true, false);

			AssetManager.AppendAssetBundleRequest(string.Format("pokemons/battle/{0}", catalog.AssetBundleName), true, (eventType, assetName, asset) =>
			{
				if (eventType == RequestEventType.Activated && asset is GameObject)
				{
					_loadObjectCnt--;
					GameObject go = UnityEngine.Object.Instantiate(asset as GameObject);
					var entity = go.GetComponent<BattlePokemonEntity>();
					if (entity != null)
						entity.Initialize(catalog, true);

					var boPokemon = go.AddComponent<BOPokemon>();
					boPokemon.Initialize(vPos, param);
					boPokemon.transform.SetParent(connector.characterCacheObjects);
					pokemons[(int)vPos] = boPokemon;
				}
			}, null);
			AssetManager.DispatchRequests();
		}
		private void StartGround() {
			var connector = GameManager.connector;
			if (connector == null)
				return;

			var setupParam = GetSetupParam();
			var arenaData = setupParam.arenaData;
			var trainerParams = setupParam.trainerParams;

			var reflectionCamera = connector.reflectionCamera;
			if (reflectionCamera != null)
			{
				bool isReflection = arenaData.ReflectionResolution > 0;
				reflectionCamera.SetActive(isReflection);
				reflectionCamera.enabled = isReflection;
				reflectionCamera.cullingMask = arenaData.ReflectionResolution > 0 ? Layer.Everything : Layer.Nothing;
			}

			var myStatus = new MyStatus();
			bool isSkirt = false;
			for (int i = 0; i < trainerParams.Length; i++)
			{
				if (!trainerParams[i].HasValue)
					continue;

				myStatus.Deserialize(trainerParams[i].Value);
				if (TrainerSystem.GetSkirtGraphicsChara(myStatus.GetModelID()) != null)
				{
					isSkirt = true;
					break;
				}
			}

			if (BattleConnector.BattleFieldObject != null)
				BattleConnector.BattleFieldObject.SetSkirtHideObjectActive(isSkirt, true, false, true);
		}
		public void CMD_StartSetup_ThrowSelf() {
			__SetComTargetReset__();

			string seqName;
			switch (GetBattleRule())
			{
				case BtlRule.BTL_RULE_SINGLE:
					m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
					m_effectBallInfo[0] = __GetBallInfo__(BtlvPos.BTL_VPOS_NEAR_1);
					m_effectBallId[0] = m_effectBallInfo[0].ballId;
					m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_NEAR_1;
					seqName = "ee450";
					if (pokemons[(int)BtlvPos.BTL_VPOS_NEAR_2] != null)
						pokemons[(int)BtlvPos.BTL_VPOS_NEAR_2].SetVisible(false);
					break;

				case BtlRule.BTL_RULE_DOUBLE:
					m_comTargetPoke[0] = BtlvPos.BTL_VPOS_NEAR_1;
					m_comTargetPoke[1] = BtlvPos.BTL_VPOS_NEAR_2;
					m_comTargetDamage[0] = BtlvPos.BTL_VPOS_NEAR_2;
					m_effectBallInfo[0] = __GetBallInfo__(BtlvPos.BTL_VPOS_NEAR_1);
					m_effectBallId[0] = m_effectBallInfo[0].ballId;
					m_effectBallInfo[1] = __GetBallInfo__(BtlvPos.BTL_VPOS_NEAR_2);
					m_effectBallId[1] = m_effectBallInfo[1].ballId;
					m_comTargetTrainer[0] = BtlvPos.BTL_VPOS_NEAR_1;
					seqName = m_battleDataTable.GetSetupIntroPlaySequenceData(BattleSetupIntroID.THROW_PLAYER_DOUBLE_NOT_EXIST_FRIEND).SeqName;
					break;

				default:
					seqName = string.Empty;
					break;
			}

			PlaySequenceCore(BattleViewDefine.Path.GetSequencePath(seqName), true);
			_subSeq = 0;
		}
		public bool CMD_WaitStartSetup_ThrowSelf() {
			switch (_subSeq)
			{
				case 0:
					if (m_sequenceSeq == BattleViewSystem.SequenceSeq.UPDATE_SEQUENCE)
					{
						SmartPoint.Components.Fader.fadeMode = SmartPoint.Components.Fader.FadeMode.Color;
						SmartPoint.Components.Fader.valid = true;
						SmartPoint.Components.Fader.FadeIn();
						_subSeq++;
					}
					return false;

				case 1:
				{
					if (m_sequenceSeq != BattleViewSystem.SequenceSeq.NONE)
						return false;

					var particleHash = m_iPtrSequenceSystem.GetParticleHashTable();
					if (particleHash == null)
						return true;

					foreach (var pair in particleHash.RawElements)
					{
						if (pair.Value == null)
							continue;

						foreach (var effect in pair.Value)
						{
							if (effect != null)
								effect.Kill(true);
						}
					}
					return true;
				}

				default:
					return true;
			}
		}
